create type public.collection_request_status as enum ('REQUESTED','ASSIGNED','ACCEPTED','ON_THE_WAY','COLLECTED','IN_TRANSIT','DELIVERED','CANCELLED');
create type public.sample_status as enum ('COLLECTED','IN_TRANSIT','DELIVERED','REJECTED');
create table public.collection_agents (id uuid primary key default gen_random_uuid(), user_id uuid not null unique references public.users(id) on delete restrict, service_area text, is_available boolean not null default true, is_verified boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.collection_requests (id uuid primary key default gen_random_uuid(), test_order_id uuid not null unique references public.test_orders(id) on delete restrict, patient_id uuid not null references public.patients(id) on delete restrict, facility_id uuid not null references public.healthcare_facilities(id) on delete restrict, collection_agent_id uuid references public.collection_agents(id) on delete set null, scheduled_at timestamptz not null, collection_address text not null, collection_city text, collection_state text, contact_name text not null, contact_phone text not null, status public.collection_request_status not null default 'REQUESTED', assigned_at timestamptz, accepted_at timestamptz, on_the_way_at timestamptz, collected_at timestamptz, in_transit_at timestamptz, delivered_at timestamptz, cancelled_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint collection_requests_address_nonempty check (length(trim(collection_address)) > 0), constraint collection_requests_contact_name_nonempty check (length(trim(contact_name)) > 0), constraint collection_requests_contact_phone_nonempty check (length(trim(contact_phone)) > 0));
create table public.samples (id uuid primary key default gen_random_uuid(), collection_request_id uuid not null unique references public.collection_requests(id) on delete restrict, test_order_id uuid not null references public.test_orders(id) on delete restrict, facility_id uuid not null references public.healthcare_facilities(id) on delete restrict, sample_type text not null, status public.sample_status not null default 'COLLECTED', collected_at timestamptz not null default now(), delivered_at timestamptz, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), constraint samples_sample_type_nonempty check (length(trim(sample_type)) > 0));
create index collection_agents_available_idx on public.collection_agents (is_available, is_verified); create index collection_requests_patient_status_idx on public.collection_requests (patient_id, status, created_at desc); create index collection_requests_agent_status_idx on public.collection_requests (collection_agent_id, status, scheduled_at); create index collection_requests_facility_status_idx on public.collection_requests (facility_id, status, scheduled_at); create index samples_order_idx on public.samples (test_order_id, created_at desc);
alter table public.collection_agents enable row level security; alter table public.collection_requests enable row level security; alter table public.samples enable row level security;

create or replace function public.set_collection_updated_at() returns trigger language plpgsql security invoker set search_path = public as $$ begin new.updated_at = now(); return new; end; $$;
drop trigger if exists collection_agents_set_updated_at on public.collection_agents; create trigger collection_agents_set_updated_at before update on public.collection_agents for each row execute function public.set_collection_updated_at(); drop trigger if exists collection_requests_set_updated_at on public.collection_requests; create trigger collection_requests_set_updated_at before update on public.collection_requests for each row execute function public.set_collection_updated_at(); drop trigger if exists samples_set_updated_at on public.samples; create trigger samples_set_updated_at before update on public.samples for each row execute function public.set_collection_updated_at();
create or replace function public.validate_collection_agent_role() returns trigger language plpgsql security invoker set search_path = public as $$ begin if not exists (select 1 from public.users u where u.id = new.user_id and u.role = 'COLLECTION_AGENT') then raise exception using errcode = '23514', message = 'Collection agent must reference a COLLECTION_AGENT user'; end if; if tg_op = 'UPDATE' and not public.is_admin() and (old.user_id <> new.user_id or old.is_verified <> new.is_verified) then raise exception using errcode = '42501', message = 'Only administrators can change agent identity or verification'; end if; return new; end; $$;
drop trigger if exists collection_agents_validate_role on public.collection_agents; create trigger collection_agents_validate_role before insert or update on public.collection_agents for each row execute function public.validate_collection_agent_role();
create or replace function public.validate_collection_request_relationship() returns trigger language plpgsql security invoker set search_path = public as $$ declare v_patient_id uuid; v_facility_id uuid; begin select patient_id, facility_id into v_patient_id, v_facility_id from public.test_orders where id = new.test_order_id and status <> 'CANCELLED'; if v_patient_id is null or v_facility_id is null then raise exception using errcode = '22023', message = 'Test order is unavailable for home collection'; end if; if new.patient_id <> v_patient_id or new.facility_id <> v_facility_id then raise exception using errcode = '23514', message = 'Collection request must match the test order'; end if; if tg_op = 'UPDATE' and (old.test_order_id <> new.test_order_id or old.patient_id <> new.patient_id or old.facility_id <> new.facility_id or old.collection_agent_id is distinct from new.collection_agent_id) then raise exception using errcode = '42501', message = 'Collection request relationships are immutable'; end if; return new; end; $$;
drop trigger if exists collection_requests_validate_relationship on public.collection_requests; create trigger collection_requests_validate_relationship before insert or update on public.collection_requests for each row execute function public.validate_collection_request_relationship();
create or replace function public.validate_collection_status_transition() returns trigger language plpgsql security invoker set search_path = public as $$ begin if tg_op = 'UPDATE' and old.status <> new.status then if old.status = 'REQUESTED' and new.status not in ('ASSIGNED','CANCELLED') then raise exception using errcode = '22023', message = 'Invalid collection status transition'; end if; if old.status = 'ASSIGNED' and new.status not in ('ACCEPTED','CANCELLED') then raise exception using errcode = '22023', message = 'Invalid collection status transition'; end if; if old.status = 'ACCEPTED' and new.status not in ('ON_THE_WAY','CANCELLED') then raise exception using errcode = '22023', message = 'Invalid collection status transition'; end if; if old.status = 'ON_THE_WAY' and new.status not in ('COLLECTED','CANCELLED') then raise exception using errcode = '22023', message = 'Invalid collection status transition'; end if; if old.status = 'COLLECTED' and new.status not in ('IN_TRANSIT','CANCELLED') then raise exception using errcode = '22023', message = 'Invalid collection status transition'; end if; if old.status = 'IN_TRANSIT' and new.status <> 'DELIVERED' then raise exception using errcode = '22023', message = 'Invalid collection status transition'; end if; if old.status in ('DELIVERED','CANCELLED') then raise exception using errcode = '22023', message = 'Terminal collection status cannot change'; end if; end if; return new; end; $$;
drop trigger if exists collection_requests_validate_transition on public.collection_requests; create trigger collection_requests_validate_transition before update on public.collection_requests for each row execute function public.validate_collection_status_transition();

create or replace function public.request_home_collection(p_test_order_id uuid, p_scheduled_at timestamptz, p_collection_address text, p_collection_city text, p_collection_state text, p_contact_name text, p_contact_phone text) returns public.collection_requests language plpgsql security definer set search_path = public as $$ declare v_order public.test_orders; v_patient_id uuid; v_request public.collection_requests; begin if auth.uid() is null then raise exception using errcode = '42501', message = 'Authentication required'; end if; select p.id into v_patient_id from public.patients p where p.user_id = auth.uid(); if v_patient_id is null then raise exception using errcode = '42501', message = 'Patient profile required'; end if; select * into v_order from public.test_orders where id = p_test_order_id and patient_id = v_patient_id and status <> 'CANCELLED'; if v_order.id is null then raise exception using errcode = '42501', message = 'Only your active test order can request collection'; end if; if exists (select 1 from public.collection_requests where test_order_id = p_test_order_id) then raise exception using errcode = '23505', message = 'A collection request already exists for this test order'; end if; insert into public.collection_requests (test_order_id, patient_id, facility_id, scheduled_at, collection_address, collection_city, collection_state, contact_name, contact_phone) values (v_order.id, v_order.patient_id, v_order.facility_id, p_scheduled_at, p_collection_address, p_collection_city, p_collection_state, p_contact_name, p_contact_phone) returning * into v_request; return v_request; end; $$;
revoke all on function public.request_home_collection(uuid, timestamptz, text, text, text, text, text) from public; grant execute on function public.request_home_collection(uuid, timestamptz, text, text, text, text, text) to authenticated;
create or replace function public.assign_collection_agent(p_request_id uuid, p_agent_id uuid) returns public.collection_requests language plpgsql security definer set search_path = public as $$ declare v_request public.collection_requests; begin if auth.uid() is null or not public.is_admin() then raise exception using errcode = '42501', message = 'Only administrators can assign collection agents'; end if; select * into v_request from public.collection_requests where id = p_request_id; if v_request.id is null then raise exception using errcode = '22023', message = 'Collection request not found'; end if; if v_request.status <> 'REQUESTED' then raise exception using errcode = '22023', message = 'Only requested collections can be assigned'; end if; if not exists (select 1 from public.collection_agents where id = p_agent_id and is_verified = true and is_available = true) then raise exception using errcode = '22023', message = 'Collection agent is unavailable or unverified'; end if; update public.collection_requests set collection_agent_id = p_agent_id, status = 'ASSIGNED', assigned_at = now() where id = p_request_id returning * into v_request; return v_request; end; $$;
revoke all on function public.assign_collection_agent(uuid, uuid) from public; grant execute on function public.assign_collection_agent(uuid, uuid) to authenticated;
create or replace function public.update_collection_status(p_request_id uuid, p_status public.collection_request_status, p_sample_type text default null, p_notes text default null) returns public.collection_requests language plpgsql security definer set search_path = public as $$ declare v_request public.collection_requests; v_agent_user_id uuid; v_patient_user_id uuid; begin if auth.uid() is null then raise exception using errcode = '42501', message = 'Authentication required'; end if; select * into v_request from public.collection_requests where id = p_request_id; if v_request.id is null then raise exception using errcode = '22023', message = 'Collection request not found'; end if; select u.user_id into v_agent_user_id from public.collection_agents a join public.users u on u.id = a.user_id where a.id = v_request.collection_agent_id; select p.user_id into v_patient_user_id from public.patients p where p.id = v_request.patient_id; if public.is_admin() or (v_agent_user_id = auth.uid() and p_status in ('ACCEPTED','ON_THE_WAY','COLLECTED','IN_TRANSIT','DELIVERED')) or (v_patient_user_id = auth.uid() and p_status = 'CANCELLED') then null; else raise exception using errcode = '42501', message = 'You are not authorized to update this collection'; end if; if p_status = 'COLLECTED' and coalesce(length(trim(p_sample_type)), 0) = 0 then raise exception using errcode = '22023', message = 'Sample type is required when collecting a sample'; end if; update public.collection_requests set status = p_status, accepted_at = case when p_status = 'ACCEPTED' then now() else accepted_at end, on_the_way_at = case when p_status = 'ON_THE_WAY' then now() else on_the_way_at end, collected_at = case when p_status = 'COLLECTED' then now() else collected_at end, in_transit_at = case when p_status = 'IN_TRANSIT' then now() else in_transit_at end, delivered_at = case when p_status = 'DELIVERED' then now() else delivered_at end, cancelled_at = case when p_status = 'CANCELLED' then now() else cancelled_at end where id = p_request_id returning * into v_request; if p_status = 'COLLECTED' then insert into public.samples (collection_request_id, test_order_id, facility_id, sample_type, status, notes) values (v_request.id, v_request.test_order_id, v_request.facility_id, trim(p_sample_type), 'COLLECTED', p_notes); elsif p_status = 'IN_TRANSIT' then update public.samples set status = 'IN_TRANSIT', notes = coalesce(p_notes, notes) where collection_request_id = v_request.id; elsif p_status = 'DELIVERED' then update public.samples set status = 'DELIVERED', delivered_at = now(), notes = coalesce(p_notes, notes) where collection_request_id = v_request.id; elsif p_notes is not null then update public.samples set notes = p_notes where collection_request_id = v_request.id; end if; return v_request; end; $$;
revoke all on function public.update_collection_status(uuid, public.collection_request_status, text, text) from public; grant execute on function public.update_collection_status(uuid, public.collection_request_status, text, text) to authenticated;

create policy collection_agents_select_self on public.collection_agents for select to authenticated using (user_id = auth.uid()); create policy collection_agents_select_admin on public.collection_agents for select to authenticated using (public.is_admin()); create policy collection_agents_insert_admin on public.collection_agents for insert to authenticated with check (public.is_admin()); create policy collection_agents_update_self on public.collection_agents for update to authenticated using (user_id = auth.uid()) with check (user_id = auth.uid()); create policy collection_agents_update_admin on public.collection_agents for update to authenticated using (public.is_admin()) with check (public.is_admin());
create policy collection_requests_select_patient on public.collection_requests for select to authenticated using (exists (select 1 from public.patients p where p.id = patient_id and p.user_id = auth.uid())); create policy collection_requests_select_agent on public.collection_requests for select to authenticated using (exists (select 1 from public.collection_agents a where a.id = collection_agent_id and a.user_id = auth.uid())); create policy collection_requests_select_admin on public.collection_requests for select to authenticated using (public.is_admin()); create policy collection_requests_update_admin on public.collection_requests for update to authenticated using (public.is_admin()) with check (public.is_admin());
create policy samples_select_patient on public.samples for select to authenticated using (exists (select 1 from public.collection_requests r join public.patients p on p.id = r.patient_id where r.id = collection_request_id and p.user_id = auth.uid())); create policy samples_select_agent on public.samples for select to authenticated using (exists (select 1 from public.collection_requests r join public.collection_agents a on a.id = r.collection_agent_id where r.id = collection_request_id and a.user_id = auth.uid())); create policy samples_select_admin on public.samples for select to authenticated using (public.is_admin()); create policy samples_update_admin on public.samples for update to authenticated using (public.is_admin()) with check (public.is_admin());
